  ApiEndpoint(
    method: 'DELETE',
    path: '/api/v0/auth/account',
    inSwagger: true,
    tags: ['auth'],
    summary: 'Delete account data (factory reset)',
    description: 'Deletes the selected aspects and logs the caller out everywhere. Pass account=true to delete only the caller\'s own account, which is what App Store Guideline 5.1.1(v) requires; the other aspects are a factory reset of the appliance. All four are opt-in and a request selecting none is rejected, so a truncated call cannot destroy anything. The JSON body\'s password field must carry the caller\'s own auth key, which is checked before anything is deleted; a raw password, which only an app from before auth keys sends, is refused with 426 (#2430); it travels in the body rather than the URL so it never reaches an access or proxy log. Attempts share the per-IP limit of the sign-in endpoints, so this endpoint cannot be used to guess the password. A reset of the database, files or devices holds the database write lock while it drops and re-migrates, so another instance serving the same install never sees it half done, and then every instance, this one included, restarts within a few seconds: expect requests to fail briefly after a 200. Repeat calls are idempotent while the account exists. External device data is reached only when devices=true; a drive that is not attached at reset time keeps its data. Deleting the last account returns the appliance to first-boot setup by design. Aspects are independent: deleting the account or the database does NOT delete stored files, and files left behind are readable by whoever sets the appliance up next — the response reports filesRetained=true whenever that happens, so pass files=true as well to erase the data itself.',
    parameters: [
      ApiParameter(
        name: 'account',
        location: ApiParameterLocation.query,
        type: 'boolean',
        description: 'Delete the caller\'s own account (users row). Does NOT delete stored files unless files=true is also passed; files left behind stay readable by whoever sets the appliance up next.',
      ),
      ApiParameter(
        name: 'database',
        location: ApiParameterLocation.query,
        type: 'boolean',
        description: 'Delete the appliance database (quark.db). Does NOT delete stored files unless files=true is also passed; files left behind stay readable by whoever sets the appliance up next.',
      ),
      ApiParameter(
        name: 'files',
        location: ApiParameterLocation.query,
        type: 'boolean',
        description: 'Delete stored files under the data directory',
      ),
      ApiParameter(
        name: 'devices',
        location: ApiParameterLocation.query,
        type: 'boolean',
        description: 'Delete the Quark data directory on attached external devices',
      ),
      ApiParameter(
        name: 'body',
        location: ApiParameterLocation.body,
        required: true,
        type: 'object',
        description: 'The caller\'s own auth key, in the password field',
      ),
    ],
    requestSchema: '{"type":"object","required":["password"],"properties":{"password":{"type":"string"}}}',
    responses: [
      ApiResponse(
        status: '200',
        description: 'OK',
        schema: '{"type":"object","properties":{"deleted":{"type":"object","properties":{"account":{"type":"boolean"},"database":{"type":"boolean"},"devices":{"type":"boolean"},"files":{"type":"boolean"}}},"filesRetained":{"type":"boolean"}}}',
      ),
      ApiResponse(
        status: '400',
        description: 'Bad Request',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '401',
        description: 'no session, or the session\'s account no longer exists',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '403',
        description: 'the auth key is wrong, or database, files or devices were requested by a non-admin',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '409',
        description: 'account=true from the only active admin while other active or disabled accounts exist; nothing is deleted',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '426',
        description: 'password is a raw password: the app is too old',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '429',
        description: 'too many attempts from this address; nothing is deleted',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '500',
        description: 'Internal Server Error',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
    ],
    callers: ['AuthService._deleteAspects'],
  ),
  ApiEndpoint(
    method: 'POST',
    path: '/api/v0/auth/login',
    inSwagger: true,
    tags: ['auth'],
    summary: 'Login',
    description: 'Authenticates with {username, authKey} and returns a session token. authKey is the standard base64 of the 32-byte key the client derived from the password and the salt GET /auth/salt returned. {username, password, authKey} is the one-time upgrade of an account GET /auth/salt calls legacy: the password is checked against the stored one, and the key, its salt and a cleared password hash are stored in one write, so the password never signs in again; a failed write refuses the sign-in with 500. An account that already has an auth key is checked by the key, and the password beside it is ignored. A body carrying password with no authKey, which only an app from before auth keys sends, is refused with 426 before anything is checked (#2430). legacyRecovery is true for an account that has no recovery key yet, such as one an admin created: the client generates a phrase and sends its key to PUT /auth/recovery-key. A pending or disabled account with the right key gets 403 with its status, so the app can tell it from a wrong password. Repeated failures lock out the client address, the account at that address, or the account from new addresses for a while: the answer is 429 with Retry-After in seconds, whether or not the username exists.',
    parameters: [
      ApiParameter(
        name: 'body',
        location: ApiParameterLocation.body,
        required: true,
        type: 'object',
        description: 'The username, the authKey, and for the upgrade the password',
      ),
    ],
    requestSchema: '{"type":"object","required":["username"],"properties":{"authKey":{"description":"AuthKey is the standard base64 of the 32-byte key the client derived\\nfrom the password and the salt GET /auth/salt returned.","type":"string"},"password":{"description":"Password, beside AuthKey, upgrades an account that has no auth key yet,\\nonce (#2430). Without AuthKey it is an old app\'s sign-in, refused with\\n426.","type":"string"},"username":{"type":"string"}}}',
    responses: [
      ApiResponse(
        status: '200',
        description: 'OK',
        schema: '{"type":"object","properties":{"legacyRecovery":{"description":"LegacyRecovery is true for an account that has no recovery key yet, such\\nas one an admin created: the client generates a phrase and sends its key\\nto PUT /auth/recovery-key.","type":"boolean"},"token":{"type":"string"}}}',
      ),
      ApiResponse(
        status: '400',
        description: 'a missing or malformed authKey',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '401',
        description: 'Unauthorized',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '403',
        description: 'status is pending or disabled',
        schema: '{"type":"object","properties":{"error":{"type":"string"},"status":{"description":"Status is pending or disabled.","type":"string"}}}',
      ),
      ApiResponse(
        status: '426',
        description: 'the body carried a password with no authKey: the app is too old',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '429',
        description: 'locked out after repeated failures; see Retry-After',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '500',
        description: 'the upgrade\'s write failed',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '503',
        description: 'the account lookup failed; nothing was checked or counted toward a lockout',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
    ],
    callers: ['AuthService.login'],
  ),
