  ApiEndpoint(
    method: 'PUT',
    path: '/api/v0/auth/password',
    inSwagger: true,
    tags: ['auth'],
    summary: 'Change the caller\'s password',
    description: 'Re-confirms the caller with password, which carries the auth key of the password the account has now, exactly as PUT /auth/recovery-key takes it; a wrong or missing key is a 403, a raw password is a 426, and nothing is written. Then replaces the account\'s auth key with newAuthKey, the standard base64 of the 32-byte key the client derived from the new password and the salt GET /auth/salt returned (#3022). chatKeys, when sent, replaces the account\'s chat identity in the same transaction, re-wrapped under the new password, exactly as /auth/recover stores it, and vaultKey likewise replaces the wraps of the account\'s vault key (storing it as the first when the account has none) and publishes vault_changed to the account\'s sessions; nothing changes if any part fails. Every other session of the account is signed out in the same transaction; this one stays signed in. Shares the sign-in rate limit, and the body is at most 8 KiB.',
    parameters: [
      ApiParameter(
        name: 'body',
        location: ApiParameterLocation.body,
        required: true,
        type: 'object',
        description: 'The caller\'s auth key, the new password\'s auth key and optionally the re-wrapped chat keys and vault key',
      ),
    ],
    requestSchema: '{"type":"object","required":["newAuthKey"],"properties":{"chatKeys":{"description":"ChatKeys is the account\'s chat identity re-wrapped under the new\\npassword, stored in the same transaction. Absent leaves the stored keys\\nas they are.","allOf":[{"type":"object","properties":{"boxPublicKey":{"type":"array","items":{"type":"integer"}},"createdAt":{"type":"string"},"kdfParams":{"description":"KdfParams is the client\'s JSON object recording the Argon2id cost.","type":"object"},"saltPw":{"type":"array","items":{"type":"integer"}},"saltRp":{"type":"array","items":{"type":"integer"}},"signPublicKey":{"type":"array","items":{"type":"integer"}},"updatedAt":{"type":"string"},"wrappedByPassword":{"type":"array","items":{"type":"integer"}},"wrappedByPhrase":{"description":"WrappedByPhrase and SaltRp are both present or both absent.","type":"array","items":{"type":"integer"}}}}]},"newAuthKey":{"description":"NewAuthKey is the standard base64 of the 32-byte key the client derived\\nfrom the new password and the salt GET /auth/salt returned.","type":"string"},"password":{"description":"Password re-confirms the caller with the auth key of the password it has\\nnow, so a session alone cannot change the password, as delete-account\\ntakes it. A raw password is refused with 426 (#2430).","type":"string"},"vaultKey":{"description":"VaultKey is the account\'s vault key re-wrapped under the new password,\\nstored in the same transaction. Absent leaves it as it is.","allOf":[{"type":"object","properties":{"createdAt":{"type":"string"},"kdfParams":{"description":"KdfParams is the client\'s JSON object recording the Argon2id cost.","type":"object"},"saltPw":{"type":"array","items":{"type":"integer"}},"saltRp":{"type":"array","items":{"type":"integer"}},"updatedAt":{"type":"string"},"wrappedByPassword":{"type":"array","items":{"type":"integer"}},"wrappedByPhrase":{"description":"WrappedByPhrase and SaltRp are both present or both absent.","type":"array","items":{"type":"integer"}}}}]}}}',
    responses: [
      ApiResponse(
        status: '204',
        description: 'No Content',
      ),
      ApiResponse(
        status: '400',
        description: 'a malformed newAuthKey, chatKeys or vaultKey',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '401',
        description: 'no session, or the session\'s account no longer exists',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '403',
        description: 'the auth key is wrong or missing',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '426',
        description: 'password is a raw password: the app is too old',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '429',
        description: 'Too Many Requests',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '500',
        description: 'Internal Server Error',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
    ],
    callers: ['AuthService.changePassword', 'AuthService.replaceVaultKeyWrap'],
  ),
  ApiEndpoint(
    method: 'POST',
    path: '/api/v0/auth/recover',
    inSwagger: true,
    tags: ['auth'],
    summary: 'Recover account',
    description: 'Resets the named account\'s password using its recoveryKey, the standard base64 of the 32-byte key the client derived from the phrase and the salt GET /auth/salt returned. A wrong key, an unknown username and an account with no recovery key all read as a wrong phrase. newAuthKey, the standard base64 of the 32-byte key the client derived from the new password and the same salt, replaces the account\'s auth key and clears its password hash. An account GET /auth/salt calls legacyRecovery recovers once with its raw recoveryPhrase in place of recoveryKey, beside newAuthKey and newRecoveryKey, the key of a phrase the client just generated, and optionally recoveryPhraseWords, how many words that phrase had (0 to 64, missing is 0, unknown): the reset stores both keys, the count and clears the phrase and password hashes. An account with a recovery key refuses every phrase as a wrong one. A recoveryPhrase without both new keys, or a newPassword, is what only an app from before auth keys sends, and is refused with 426 (#2430). chatKeys, when sent, replaces the account\'s chat identity in the same transaction: the client fetched it from /auth/recover/keys, opened it with the phrase and re-wrapped it under the new password (#2416). vaultKey, when sent, likewise replaces the wraps of the account\'s vault key in the same transaction, fetched from /auth/recover/vault-key and re-wrapped the same way (storing it as the first when the account has none), and publishes vault_changed to the account\'s sessions (#3459). The body is at most 8 KiB.',
    parameters: [
      ApiParameter(
        name: 'body',
        location: ApiParameterLocation.body,
        required: true,
        type: 'object',
        description: 'The account, its recovery key or legacy phrase, the new keys, and optionally its re-wrapped chat keys and vault key',
      ),
    ],
    requestSchema: '{"type":"object","required":["username"],"properties":{"chatKeys":{"description":"ChatKeys is the account\'s chat identity re-wrapped under the new\\npassword, stored in the same transaction as the reset (#2416). Absent\\nleaves the stored keys as they are.","allOf":[{"type":"object","properties":{"boxPublicKey":{"type":"array","items":{"type":"integer"}},"createdAt":{"type":"string"},"kdfParams":{"description":"KdfParams is the client\'s JSON object recording the Argon2id cost.","type":"object"},"saltPw":{"type":"array","items":{"type":"integer"}},"saltRp":{"type":"array","items":{"type":"integer"}},"signPublicKey":{"type":"array","items":{"type":"integer"}},"updatedAt":{"type":"string"},"wrappedByPassword":{"type":"array","items":{"type":"integer"}},"wrappedByPhrase":{"description":"WrappedByPhrase and SaltRp are both present or both absent.","type":"array","items":{"type":"integer"}}}}]},"newAuthKey":{"description":"NewAuthKey is the standard base64 of the 32-byte key derived from the\\nnew password and the salt GET /auth/salt returned (#2430).","type":"string"},"newPassword":{"description":"NewPassword is the raw password an app from before auth keys sends. It\\nis refused with 426.","type":"string"},"newRecoveryKey":{"description":"NewRecoveryKey is the standard base64 of the 32-byte key derived from a\\nphrase the client just generated and the same salt. A legacy phrase\\nrecovery must carry it, so the account leaves the phrase the Quark saw.","type":"string"},"recoveryKey":{"description":"RecoveryKey is the standard base64 of the 32-byte key derived from the\\nphrase and the salt GET /auth/salt returned (#2430).","type":"string"},"recoveryPhrase":{"description":"RecoveryPhrase is a legacy account\'s raw phrase, taken once in place of\\nRecoveryKey beside NewAuthKey and NewRecoveryKey (#2430). Without both it\\nis an old app\'s recovery, refused with 426.","type":"string"},"recoveryPhraseWords":{"description":"RecoveryPhraseWords is how many words the phrase behind NewRecoveryKey had\\n(#3183). Missing reads as 0, unknown, which GET /auth/status calls\\nshort. Between 0 and 64.","type":"integer"},"username":{"type":"string"},"vaultKey":{"description":"VaultKey is the account\'s vault key re-wrapped under the new password,\\nstored in the same transaction (#3459). Absent leaves it as it is.","allOf":[{"type":"object","properties":{"createdAt":{"type":"string"},"kdfParams":{"description":"KdfParams is the client\'s JSON object recording the Argon2id cost.","type":"object"},"saltPw":{"type":"array","items":{"type":"integer"}},"saltRp":{"type":"array","items":{"type":"integer"}},"updatedAt":{"type":"string"},"wrappedByPassword":{"type":"array","items":{"type":"integer"}},"wrappedByPhrase":{"description":"WrappedByPhrase and SaltRp are both present or both absent.","type":"array","items":{"type":"integer"}}}}]}}}',
    responses: [
      ApiResponse(
        status: '200',
        description: 'OK',
        schema: '{"type":"object"}',
      ),
      ApiResponse(
        status: '400',
        description: 'Bad Request',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
      ApiResponse(
        status: '403',
        description: 'status is pending or disabled',
        schema: '{"type":"object","properties":{"error":{"type":"string"},"status":{"description":"Status is pending or disabled.","type":"string"}}}',
      ),
      ApiResponse(
        status: '426',
        description: 'the body carried newPassword, or a phrase without both new keys: the app is too old',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
    ],
    callers: ['AuthService.recover'],
  ),
  ApiEndpoint(
