  ApiEndpoint(
    method: 'GET',
    path: '/api/v0/storage/protection',
    inSwagger: true,
    tags: ['storage'],
    summary: 'Get data protection status',
    description: 'Reports how protected the files are, per drive. A data drive is every connected drive that is not a snapshot-backup drive: built-in storage, the default-storage drive, and unassigned drives. A backup drive is every snapshot-backup drive, connected or not. A backup drive\'s copy of a data drive is its newest complete run folder under backups/ whose manifest names that data drive, dated when the run completed. An attached backup drive\'s run folders are read on every request, and a backup drive that is away answers from the scan cached when it was last attached; one never scanned has no copies. A copy counts when the backup drive\'s health verdict is not replace-soon, the copy is inside 30 days, and the backup drive is on a different physical disk from the data drive; two partitions of one backup disk count once per data drive. A data drive with no counting copy is unprotected, one is basic, and two or more is protected. level is the weakest data drive\'s. sentence is one plain sentence. nextStep is start-backup when a backup drive could give the weakest data drive another counting copy, assign-backup-role when none can, and keep-one-elsewhere when every data drive is protected. dataDrives lists each data drive\'s copies with whether each counts and why not. backupDrives lists each backup drive\'s state (retired, receiving, away, no-copies, current, or behind, first match wins) and the data drives it holds. Refetch when a backup completes or fails (backup_completed, backup_failed).',
    responses: [
      ApiResponse(
        status: '200',
        description: 'OK',
        schema: '{"type":"object","properties":{"backupDrives":{"description":"BackupDrives lists every snapshot-backup drive, connected or not.","type":"array","items":{"type":"object","properties":{"holds":{"description":"Holds is one per current data drive this drive has a copy of, newest first.","type":"array","items":{"type":"object","properties":{"copiedAt":{"type":"string"},"name":{"type":"string"},"serial":{"type":"string"}}}},"name":{"type":"string"},"newestCopy":{"description":"NewestCopy is the newest of Holds. Null when Holds is empty.","type":"string"},"serial":{"type":"string"},"state":{"description":"State is retired, receiving, away, no-copies, current, or behind; the first that applies.","type":"string","enum":["no-copies","receiving","current","behind","away","retired"]}}}},"dataDrives":{"description":"DataDrives lists every connected drive that is not a backup drive, built-in storage first.","type":"array","items":{"type":"object","properties":{"copies":{"description":"Copies is one per backup drive with a copy of this drive, newest first.","type":"array","items":{"type":"object","properties":{"backupName":{"type":"string"},"backupSerial":{"type":"string"},"copiedAt":{"type":"string"},"counts":{"description":"Counts is whether this copy protects the drive.","type":"boolean"},"reason":{"description":"Reason is why Counts is false, in one plain sentence. Empty when Counts is true.","type":"string"}}}},"level":{"description":"Level is unprotected (no counting copy), basic (one), or protected (two or more).","type":"string","enum":["unprotected","basic","protected"]},"name":{"type":"string"},"serial":{"description":"Serial is empty for built-in storage.","type":"string"}}}},"level":{"description":"Level is the weakest data drive\'s: unprotected, basic, or protected.","type":"string","enum":["unprotected","basic","protected"]},"nextStep":{"description":"NextStep is assign-backup-role, start-backup, or keep-one-elsewhere.","type":"string","enum":["assign-backup-role","start-backup","keep-one-elsewhere"]},"sentence":{"description":"Sentence is one plain sentence describing the whole Quark from its weakest data drive.","type":"string"}}}',
      ),
      ApiResponse(
        status: '500',
        description: 'Internal Server Error',
        schema: '{"type":"object","properties":{"contentType":{"type":"string","enum":["text/html","application/json"],"x-enum-varnames":["ContentTypeHTML","ContentTypeJSON"]},"data":{},"error":{},"statusCode":{"type":"integer"}}}',
      ),
    ],
    callers: ['DataProtectionService.fetch'],
  ),
